!function(e){function r(r){for(var t,n,o=r[0],m=r[1],s=r[2],d=0,c=[];d<o.length;d++)n=o[d],Object.prototype.hasOwnProperty.call(i,n)&&i[n]&&c.push(i[n][0]),i[n]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(g&&g(r);c.length;)c.shift()();return p.push.apply(p,s||[]),a()}function a(){for(var e,r=0;r<p.length;r++){for(var a,n=p[r],o=!0,m=1;m<n.length;m++)a=n[m],0!==i[a]&&(o=!1);o&&(p.splice(r--,1),e=t(t.s=n[0]))}return e}function t(r){if(n[r])return n[r].exports;var a=n[r]={i:r,l:!1,exports:{}};return e[r].call(a.exports,a,a.exports,t),a.l=!0,a.exports}var n={},i={36:0},p=[];t.m=e,t.c=n,t.d=function(e,r,a){t.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:a})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,r){if(1&r&&(e=t(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var a=Object.create(null);if(t.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var n in e)t.d(a,n,function(r){return e[r]}.bind(null,n));return a},t.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(r,"a",r),r},t.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=r,o=o.slice();for(var s=0;s<o.length;s++)r(o[s]);var g=m;p.push([64,0]),a()}({64:function(e,r,a){"use strict";a.r(r);var t=a(0);Object(t.a)("de","army",a(65),a(1))},65:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"自行火炮","link":"de_army#de_army_spgun"}],"model":"“卡尔”重型迫击炮车","description":"<p>“卡尔”重型迫击炮车是德国在二战早期研制的，1939年生产出样车，用参与研发的“卡尔·贝克”将军命名。该型炮车有二种型号，一种是040型，安装600mm口径的迫击炮，底盘有8对负重轮，1940年11月至1941年8月间一共生产了6辆；另一种是041型，安装540mm口径火炮，底盘有11对负重轮，1942年5月德军订购了6辆，但至1943年8月只交付了3辆。该型炮车交付给德军628和883重型炮兵营，部署在东线苏联战场，曾在1942年进攻苏联塞瓦斯托波尔战斗中发挥了重要作用。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_spgunKarl_11.jpg","description":"<h6>“卡尔”重型迫击炮车<br>型号：Cerät 040 Karl（600）</h6><p>040型，安装600mm口径的迫击炮，底盘有8对负重轮。</p>","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_12.jpg","description":"<h6>“卡尔”重型迫击炮车<br>型号：Cerät 041 Karl（540）</h6><p>041型，安装540mm口径火炮，底盘有11对负重轮。</p>","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_13.jpg","description":"<h6>“卡尔”重型迫击炮弹运输车（Ⅳ号坦克底盘）</h6><p>由于600mm的迫击炮弹重量达2.17吨，而高度比一个人的身高还要高，受限于炮车的的容积与重量，因此“卡尔”炮车的重型迫击炮弹只能由专门的弹药运输车装载和运送。</p>","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_14.jpg","description":"<p>每辆“卡尔”重型迫击炮弹运输车只能装载4发炮弹，这是弹药车吊起炮弹的状况。</p>","caption":""}],"part2title":"战场上的“卡尔”重型迫击炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_spgunKarl_21.jpg","description":"1943-1944年战场上的“卡尔”重型迫击炮车","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_22.jpg","description":"正在发射中的“卡尔”重型迫击炮车（绘图）","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_23.jpg","description":"一辆Gerät 040“卡尔”重型迫击炮车和一辆运载600mm炮弹的Mun.PzKpfw.IV F型重型迫击炮弹运输车。注意后者敞开的弹药箱。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_24.jpg","description":"两台580吨制动机构给跑车载具带来104吨的压力。“卡尔”重型迫击炮车的炮管和载车都有两套反后坐力机构，其压力由60at增长至138at（at为工程大气压单位，1at=1Kgf/cm2=98.07KPa）。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_25.jpg","description":"拥有120吨自重和580马力柴油发动机、全履带式底盘的“卡尔”600mm重型迫击炮车最大行驶时速为10公里/小时，其对地面的压力值仅为1.7公斤/平方厘米。这幅图片拍摄于1941年的俄罗斯，该炮车正在驶入阵地。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_26.jpg","description":"这辆Mun.PzKpfw.IV重型迫击炮弹运输车使用自带绞车卸载2.117吨重的混凝土穿甲炮弹，这种炮弹可击穿2.5米厚的混凝土建筑物或4米厚的装甲板。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_27.jpg","description":"“卡尔”重型迫击炮车的众多车组人员正在装填炮弹，如此又大又重的炮弹，在当时只能人工装填的情况下是相当困难的。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_28.jpg","description":"在德军军官的注视下，这门“卡尔”重型迫击炮车的车组人员正在作战前准备。图中可见到该炮炮座底盘已经下沉至其11根反后坐力滚筒的位置，弹药输送车也已停靠在了旁边，10分钟内这门重迫击炮就能做好发射准备。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_29.jpg","description":"1942年6月，乌克兰克里米亚塞瓦斯托波尔地区，进入发射阵地的Gerät 040“卡尔”600mm重型迫击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_30.jpg","description":"正在发射状态中的德国最重型、同时也是世界上最重型的迫击炮。其炮管处反后坐力的减震气压瓶在此图中清晰可见。该炮为电驱动发射，其后坐压力值为700吨。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_31.jpg","description":"1944年8月28日，波兰华沙，总统府建筑物被一枚卡尔重型迫击炮车的600mm炮弹击中爆炸时的著名照片。","caption":""},{"image":"imgs/de/army/de_army_spgunKarl_32.jpg","description":"被卡尔重型迫击炮击毁的华沙邮政总局建筑物。","caption":""}]}')}});